def solve_tiles(allow_rotate=False, max_solutions=5):
    bit={cell:1<<i for i,cell in enumerate(sorted(target))}
    full=(1<<len(bit))-1
    variants=[]
    for name,pat in pieces:
        pats=[pat]
        if allow_rotate:
            from copy import deepcopy
            rot=[list(x) for x in zip(*pat[::-1])]
            if rot!=pat: pats.append(rot)
        options=[]
        seen=set()
        for p in pats:
            h,w=len(p),len(p[0])
            for r in range(9-h+1):
                for c in range(20-w+1):
                    cells={(r+i,c+j) for i in range(h) for j in range(w)}
                    if cells<=target:
                        mask=sum(bit[x] for x in cells)
                        key=(mask,tuple(map(tuple,p)))
                        if key not in seen:
                            seen.add(key); options.append((mask,r,c,p))
        variants.append((name,options))
    # candidate list by cell and piece idx
    bycell={x:[] for x in target}
    for i,(name,opts) in enumerate(variants):
        for oi,(mask,r,c,p) in enumerate(opts):
            for x in target:
                if mask & bit[x]: bycell[x].append((i,oi,mask,r,c,p))
    sol=[]; count=0; calls=0
    def rec(occupied, used, chosen):
        nonlocal count,calls
        calls+=1
        if occupied==full:
            count+=1
            sol.append(chosen.copy())
            return count>=max_solutions
        best=None; bestcand=None
        for x,b in bit.items():
            if occupied&b: continue
            cand=[q for q in bycell[x] if not (used>>q[0]&1) and not (occupied&q[2])]
            if not cand: return False
            if bestcand is None or len(cand)<len(bestcand):
                best,bestcand=x,cand
                if len(cand)==1: break
        for i,oi,mask,r,c,p in bestcand:
            if rec(occupied|mask, used|(1<<i), chosen+[(i,oi,r,c,p)]): return True
        return False
    rec(0,0,[])
    return count,calls,sol,variants
